fn reverse(a: &Vec<i32>) -> Vec<i32> {
    // Pre-allocate the result vector with the same capacity as the input
    let mut result = Vec::with_capacity(a.len());
    // Iterate the input in reverse order and push each element into `result`
    for &x in a.iter().rev() {
        result.push(x);
    }
    result
}

